<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Http\Request;
final class PlatformGuests
{
 public static function accountFields():array{return ['id','name','profile_name','email','contact_email','phone','email_verified','created_at','updated_at'];}
 public static function account(int $id):array{$a=DB::table('guest_accounts')->select(self::accountFields())->find($id);abort_unless($a,404);return (array)$a;}
 public static function version(array $row):string{return hash('sha256',json_encode($row,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));}
 public static function canonical(array $c,array $accounts):array{if(!empty($c['guestId'])&&isset($accounts[$c['guestId']])){$a=$accounts[$c['guestId']];if(!empty($a->profile_name))$c['name']=$a->profile_name;$c['email']=$a->contact_email??$a->email??'';$c['phone']=$a->phone??$c['phone']??'';}return $c;}
 public static function directory(Request $r):array
 {
  $v=$r->validate(['q'=>'nullable|string|max:150','providerId'=>'nullable|integer|min:1','kind'=>'nullable|in:all,account,local','blocked'=>'nullable|in:all,yes,no','visibility'=>'nullable|in:active,deleted,all']);$accounts=DB::table('guest_accounts')->select(self::accountFields())->get()->keyBy('id');$rows=[];$providers=[];
  foreach($accounts as $a)$rows['a:'.$a->id]=['key'=>'a:'.$a->id,'kind'=>'account','id'=>$a->id,'name'=>$a->profile_name?:$a->name,'email'=>$a->contact_email??$a->email??'','phone'=>$a->phone??'','providers'=>[],'blocked'=>false,'deleted'=>false];
  foreach(DB::table('salon_state')->select('id','data->settings->name as name','data->clients as clients')->orderBy('id')->cursor() as $s){$providers[]=['id'=>$s->id,'name'=>$s->name];foreach(json_decode($s->clients??'[]',true)?:[] as $raw){$deleted=!Clients::visible($raw);if(($v['visibility']??'active')==='active'&&$deleted)continue;if(($v['visibility']??'active')==='deleted'&&!$deleted)continue;$c=self::canonical($raw,$accounts->all());$link=['providerId'=>$s->id,'providerName'=>$s->name,'clientId'=>$c['id'],'blocked'=>!empty($c['blockedOnline']),'deleted'=>$deleted];$key=!empty($c['guestId'])&&isset($rows['a:'.$c['guestId']])?'a:'.$c['guestId']:'c:'.$s->id.':'.$c['id'];if(!isset($rows[$key]))$rows[$key]=['key'=>$key,'kind'=>'local','id'=>$c['id'],'providerId'=>$s->id,'name'=>$c['name'],'email'=>$c['email']??'','phone'=>$c['phone']??'','providers'=>[],'blocked'=>false,'deleted'=>$deleted];$rows[$key]['providers'][]=$link;$rows[$key]['blocked']=$rows[$key]['blocked']||$link['blocked'];}}
  $fold=fn($s)=>mb_strtolower(Str::ascii((string)$s));$q=$fold($v['q']??'');$digits=Clients::phone($q);$rows=array_values(array_filter($rows,function($row)use($v,$q,$digits,$fold){if(($v['visibility']??'active')==='deleted'&&!collect($row['providers'])->contains('deleted',true))return false;if(($v['kind']??'all')!=='all'&&$row['kind']!==$v['kind'])return false;if(!empty($v['providerId'])&&!collect($row['providers'])->contains('providerId',(int)$v['providerId']))return false;if(($v['blocked']??'all')==='yes'&&!$row['blocked'])return false;if(($v['blocked']??'all')==='no'&&$row['blocked'])return false;return !$q||str_contains($fold($row['name'].' '.$row['email'].' '.$row['phone'].' '.implode(' ',array_column($row['providers'],'providerName'))),$q)||($q===$fold($row['id']))||(strlen($digits)>=3&&str_contains(Clients::phone($row['phone']),$digits));}));usort($rows,fn($a,$b)=>strnatcasecmp($a['name'],$b['name'])?:strcmp($a['key'],$b['key']));return HistoryPage::items($rows,$r,20)+['providers'=>$providers];
 }
 public static function links(int $guest):array{$out=[];foreach(DB::table('salon_state')->select('id','data->settings->name as name','data->clients as clients')->orderBy('id')->cursor() as $s)foreach(json_decode($s->clients??'[]',true)?:[] as $c)if((int)($c['guestId']??0)===$guest)$out[]=['providerId'=>$s->id,'providerName'=>$s->name,'clientId'=>$c['id'],'name'=>$c['name'],'deleted'=>!Clients::visible($c),'blocked'=>!empty($c['blockedOnline'])];return $out;}
 public static function client(int $provider,string $id):array{return app(Tenant::class)->run($provider,function()use($id){abort_unless(DB::table('salon_state')->where('id',app(Tenant::class)->id)->exists(),404);$s=app(SalonStore::class)->read();$c=collect($s['clients'])->firstWhere('id',$id);abort_unless($c,404);return ['client'=>array_intersect_key($c,array_flip(['id','name','email','phone','guestId','notes','createdAt','deletedAt','blockedOnline','blockedReason','blockedAt','nameManaged'])),'version'=>self::version($c),'provider'=>['id'=>app(Tenant::class)->id,'name'=>$s['settings']['name']]];});}
 public static function history(Request $r,array $links):array
 {
  $v=$r->validate(['history'=>'sometimes|in:bookings,payments,passes,points,reviews']);$type=$v['history']??'bookings';$items=[];
  foreach(collect($links)->groupBy('providerId') as $provider=>$profiles){app(Tenant::class)->run((int)$provider,function()use(&$items,$profiles,$type,$provider){$s=app(SalonStore::class)->read();$ids=$profiles->pluck('clientId')->all();$bookings=array_values(array_filter($s['bookings'],fn($b)=>in_array($b['clientId']??null,$ids,true)));$bookingIds=array_column($bookings,'id');$records=match($type){'bookings'=>$bookings,'payments'=>array_values(array_filter($s['payments']??[],fn($p)=>in_array($p['bookingId']??null,$bookingIds,true))),'passes'=>array_values(array_filter($s['clientPasses']??[],fn($p)=>in_array($p['clientId']??null,$ids,true))),'points'=>array_values(array_filter($s['loyalty']['ledger']??[],fn($p)=>in_array($p['clientId']??null,$ids,true))),'reviews'=>array_values(array_filter($s['reviews']??[],fn($p)=>in_array($p['bookingId']??null,$bookingIds,true)))};foreach($records as $record){$fields=match($type){'bookings'=>['id','name','phone','email','start','end','status','attendance','services','serviceSnapshot','pricing','staff'],'payments'=>['id','bookingId','amount','paidAt','method','status','note','source'],'passes'=>['id','name','title','remaining','total','uses','expiresAt','issuedAt','revokedAt'],'points'=>['id','delta','type','at','note'],'reviews'=>['id','score','text','direction','createdAt']};$items[]=array_intersect_key($record,array_flip($fields))+['providerId'=>(int)$provider,'providerName'=>$s['settings']['name']];}});}
  usort($items,fn($a,$b)=>strcmp($b['start']??$b['paidAt']??$b['at']??$b['createdAt']??$b['created_at']??'',$a['start']??$a['paidAt']??$a['at']??$a['createdAt']??$a['created_at']??''));return HistoryPage::items($items,$r,match($type){'passes','reviews'=>5,'points'=>10,default=>20})+['history'=>$type];
 }
}
